// Inverse-rarity weight: higher = more common. Ordered common -> rare.
export const TYPE_WEIGHTS = Object.freeze({
  Fine: 1000, Nice: 750, Good: 500, Rare: 350, Wild: 275, Baby: 230,
  Epic: 200, Sus: 175, Brave: 150, Rickroll: 125, Reverse: 100, Superior: 80,
  Trash: 50, Legendary: 35, Mythic: 25, '8bit': 20, Corrupt: 15, Professor: 10,
  Divine: 8, Real: 5, Ultimate: 3, eGirl: 2,
});

export const CAT_TYPES = Object.freeze(Object.keys(TYPE_WEIGHTS));

export const TOTAL_WEIGHT = Object.values(TYPE_WEIGHTS).reduce((a, b) => a + b, 0); // 4108

/** A cat's score. Rarer cat -> higher value. */
export function valueOf(type) {
  return TOTAL_WEIGHT / TYPE_WEIGHTS[type];
}

/** Chance this type is chosen on a spawn, as a fraction of 1. */
export function probabilityOf(type) {
  return TYPE_WEIGHTS[type] / TOTAL_WEIGHT;
}

/** Weighted random pick over TYPE_WEIGHTS. */
export function rollCatType(rng = Math.random) {
  let r = rng() * TOTAL_WEIGHT;
  for (const type of CAT_TYPES) {
    r -= TYPE_WEIGHTS[type];
    if (r < 0) return type;
  }
  return CAT_TYPES[0]; // float dust
}

// Legendary and above. Quests and achievements call these "rare".
export const RARE_TIER_INDEX = CAT_TYPES.indexOf('Legendary');
export function isRare(type) {
  const i = CAT_TYPES.indexOf(type);
  return i >= 0 && i >= RARE_TIER_INDEX;
}

/** The next rarer type, or null at the top. Used by prisms. */
export function upgradeType(type) {
  const i = CAT_TYPES.indexOf(type);
  return i >= 0 && i < CAT_TYPES.length - 1 ? CAT_TYPES[i + 1] : null;
}

// ── Spawn timing (seconds) ───────────────────────────────────────────────────
export const DEFAULT_SPAWN_MIN = 60;
export const DEFAULT_SPAWN_MAX = 600;
export const MIN_SPAWN_FLOOR = 20;   // admins can't go below this
export const RESPAWN_GRACE = 10;     // padding on yet_to_spawn so the sweeper doesn't double-fire
export const SWEEP_INTERVAL_MS = 5 * 60 * 1000;

// ── Catching ─────────────────────────────────────────────────────────────────
export const CATCH_WORD = 'cat';
export const BELATED_WINDOW_MS = 5000;      // late catchers still get a cat
export const BELATED_WINDOW_RAIN_MS = 1000;
export const BELATED_WINDOW_LEGACY_MS = 3000;
export const MAX_CATCHERS = 4;              // winner + 3 belated
export const ANTI_DOUBLE_CATCH_MS = 5 * 60 * 1000;

/** Rarer cats more often trigger the post-catch bonus minigame. */
export function bonusChance(type) {
  const x = TOTAL_WEIGHT / TYPE_WEIGHTS[type] - 0.7;
  return x > 1 ? 0.02 * Math.log2(x) : 0;
}

// ── Cat rain ─────────────────────────────────────────────────────────────────
export const RAIN_CAT_COUNT = 10;
export const RAIN_MIN_DELAY = 1;
export const RAIN_MAX_DELAY = 2;

// ── Prisms (prestige) ────────────────────────────────────────────────────────
// Crafting costs one of EVERY type. Owning prisms upgrades caught cats a tier.
export function prismGlobalBoost(totalPrisms) {
  return 0.06 * Math.log(2 * totalPrisms + 1);
}
export function prismUserBoost(totalPrisms, ownPrisms) {
  return prismGlobalBoost(totalPrisms) + 0.05 * Math.log(2 * ownPrisms + 1);
}

export const EMOJI_FALLBACK = '🔳';
